package com.example

import com.example.ExamQuestionHelper.QSpec

internal object BuddhismG11LiveExamEconomyBank1 {
  private const val T = "බෞද්ධ ආර්ථික දර්ශනය හා පරිසර සංරක්ෂණය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("බෞද්ධ ආර්ථික දර්ශනයට අනුව පුද්ගලයෙකු ධනය ඉපයිය යුතු මූලික ප්‍රතිපත්තිය කුමක්ද?", "දැහැමිව හා අනුන්ට හිංසාවක් නොවන ලෙස (සම්මා ආජීවයෙන්)", "ඕනෑම අයුරකින් ලාභ ලැබීමෙන්", "අනුන් රවටා ධනය රැස් කිරීමෙන්", "පරිසරය විනාශ කර ධනය සෙවීමෙන්", "සම්මා ආජීවය යනු ධාර්මික රැකියාවකින් දිවි පෙවෙත ගෙන යෑමයි."),
    q("ආර්ය අෂ්ටාංගික මාර්ගයේ දැක්වෙන නිවැරදි ජීවන වෘත්තිය හඳුන්වන අංගය කුමක්ද?", "සම්මා ආජීව", "සම්මා කම්මන්ත", "සම්මා වායාම", "සම්මා සති", "අනුන්ට හානි නොවන දැහැමි කර්මාන්තවලින් ජීවත් වීම සම්මා ආජීවයයි."),
    q("බෞද්ධයන් විසින් නොකළ යුතු අකැප වෙළඳාම් පහ හඳුන්වන්නේ කුමන නමින්ද?", "පංච වණිජ්ජා", "පංච බලි", "පංච නීවරණ", "පංච ශීල", "ආයුධ, සතුන්, මස්, මත්ද්‍රව්‍ය, විෂ වෙළඳාම පංච වණිජ්ජා නම් වේ."),
    q("පංච වණිජ්ජා හෙවත් අකැප වෙළඳාම් පහට අයත් නොවන්නේ පහත කුමන වෙළඳාමද?", "වස්ත්‍ර හා පොත්පත් වෙළඳාම", "සත්ථ වණිජ්ජා (ආයුධ වෙළඳාම)", "මජ්ජ වණිජ්ජා (මත්පැන් වෙළඳාම)", "විස වණිජ්ජා (වස විෂ වෙළඳාම)", "මිනිස් සමාජයට හා සතුන්ට හානි නොවන වස්ත්‍ර, ධාන්‍ය, පොත්පත් ආදිය කැප වෙළඳාම් වේ."),
    q("'සත්ත වණිජ්ජා' යනුවෙන් තහනම් කර ඇති වෙළඳාම කුමක්ද?", "වහල් සේවය සඳහා මිනිසුන් හා සතුන් විකිණීම", "මල් විකිණීම", "ආභරණ විකිණීම", "ධාන්‍ය විකිණීම", "මනුෂ්‍ය ගෞරවය හා සත්ව අයිතීන් උල්ලංඝනය වන සත්ව වෙළඳාම බුදුදහම ප්‍රතික්ෂේප කරයි."),
    q("'මංස වණිජ්ජා' යනු කවර වෙළඳාමක්ද?", "සතුන් මරා මස් විකිණීම", "කෘෂි බෝග විකිණීම", "මැණික් විකිණීම", "ඖෂධ විකිණීම", "ප්‍රාණඝාතයට අනුබල ලැබෙන මස් වෙළඳාම අකැප වෙළඳාමකි."),
    q("මත්පැන් හා මත්ද්‍රව්‍ය අලෙවිය හඳුන්වන 'මජ්ජ වණිජ්ජා' තහනම් කර ඇත්තේ ඇයි?", "පුද්ගල සිහිනුවණ හා සමාජ සදාචාරය විනාශ කරන බැවින්", "ලාභය අඩු බැවින්", "භාණ්ඩ ප්‍රවාහනය අපහසු බැවින්", "වර්ණය අප්‍රිය බැවින්", "මත්ද්‍රව්‍ය සමාජ අපරාධ හා පවුල් බිඳවැටීමට මුල් වේ."),
    q("අනුන් රැවටීම සඳහා තුලාකූට, කංසකූට ආදී ක්‍රම භාවිත කිරීම බුදුදහමේ හෙළා දැක ඇත. 'තුලාකූට' යනු කුමක්ද?", "හොර තරාදිවලින් කිරා මැන පාරිභෝගිකයා රැවටීම", "බාල රන් විකිණීම", "මුදල් සොරකම් කිරීම", "රාජ්‍ය නීති කැඩීම", "වෙළඳාමේදී තුලාකූට, කංසකූට, මානකූට යන වංචනික ක්‍රමවලින් වැළකිය යුතුය."),
    q("සිඟාලෝවාද සූත්‍රයට අනුව ගිහියෙකු තමා දැහැමින් උපයන ධනය කොටස් හතරකට බෙදා වියදම් කළ යුතුය. ඊට අයත් වන්නේ කෙසේද?", "එක් කොටසක් පරිභෝජනයට, දෙකක් ආයෝජනයට, එකක් ආපදා සඳහා තැන්පත් කිරීමට", "සතරම විනෝදයට වියදම් කිරීමට", "සතරම පොළොවේ වැළලීමට", "තුනක් පරිභෝජනයට හා එකක් නාස්තියට", "චතුධා භෝගේ විභජේය්‍ය යනුවෙන් දැක්වෙන බෞද්ධ ආර්ථික කළමනාකරණ ක්‍රමයයි."),
    q("උපයන ධනයෙන් කොටස් දෙකක් (50%) කර්මාන්ත හා ව්‍යාපාර දියුණු කිරීමට යෙදවීම වර්තමාන ආර්ථික විද්‍යාවේ හඳුන්වන්නේ කුමක් ලෙසද?", "ප්‍රතිආයෝජනය (Re-investment)", "අධිපරිභෝජනය", "උද්ධමනය", "බදු ගෙවීම", "ව්‍යාපාරය දිනෙන් දින දියුණු කිරීමට ධනයෙන් අඩක් කර්මාන්තයේ යෙදවිය යුතුය."),
    q("ධනයෙන් හතරෙන් එක් කොටසක් (25%) ආපදා හා හදිසි අවස්ථා වෙනුවෙන් තැන්පත් කර තැබීම හඳුන්වන්නේ කෙසේද?", "ඉතිරි කිරීම හෙවත් සුරක්ෂිත නිධානය", "විනාශ කිරීම", "අතිරික්ත වියදම", "ණය ගැනීම", "හදිසි රෝගාබාධ හා දුර්භික්ෂ සඳහා ආපදා ආරක්ෂණ ඉතිරියක් තිබිය යුතුය."),
    q("බෞද්ධ ආර්ථික දර්ශනයේදී ධනය උපයා ගැනීම උපමා කර ඇත්තේ කුමකටද?", "මල නොතළා රොන් ගන්නා බඹරෙකුට හා වේයන් තුඹස බඳින අයුරට", "ගඟක් හරහා බඳින වේල්ලකට", "කැලෑව ගිනි තැබීමකට", "සතුන් දඩයම් කිරීමකට", "අනුන්ට පීඩා නොකර ක්‍රමානුකූලව ධනය රැස් කළ යුතු බව සිඟාලෝවාද සූත්‍රයේ දැක්වේ."),
    q("බඹරෙකු මලෙන් රොන් ගැනීමේ උපමාවෙන් බෞද්ධ ආර්ථික විද්‍යාව උගන්වන්නේ කුමක්ද?", "පාරිභෝගිකයාට හා පරිසරයට හානි නොකර සාධාරණ ලාභයක් ලැබීම", "පරිසරය සම්පූර්ණයෙන් විනාශ කිරීම", "අධික මිල ගණන් අය කිරීම", "ශ්‍රමිකයන් සූරා කෑම", "මලේ වර්ණය හා සුවඳ නොනසා පැණි ගන්නා සේ සමාජයට හිතකරව ඉපයිය යුතුය."),
    q("වේයන් තුඹසක් ගොඩනැගීමේ උපමාවෙන් බුදුදහම අවධාරණය කරන්නේ කුමක්ද?", "කුඩා ප්‍රමාණවලින් ක්‍රමානුකූලව උත්සාහයෙන් ධනය ඉතිරි කිරීම", "එක් දිනකින් කෝටිපතියෙකු වීමට සූදු කෙළීම", "ණය වී වියදම් කිරීම", "කම්මැලි වීම", "ස්ථිරසාර ඉතිරි කිරීමේ පුරුද්දෙන් මහා සම්පතක් ගොඩනැගෙන බව පෙන්වයි."),
    q("ධනය ඉපයීමේදී පුද්ගලයෙකු 'මක්ඛිකා' (මැස්සන්) මෙන් නොවී 'භමර' (බඹරුන්) මෙන් විය යුතු යැයි දැක්වෙන්නේ ඇයි?", "පිරිසිදුව හා අන් අයට පීඩා නොදී දැහැමිව ඉපයිය යුතු බැවින්", "රාත්‍රියේ වැඩ කළ යුතු බැවින්", "කණ්ඩායම් වශයෙන් විනාශ කළ යුතු බැවින්", "ඉක්මනින් මිය යන බැවින්", "ධනයේ මාර්ගය පිරිසිදු විය යුතු බව ඉන් කියවේ."),
    q("දැහැමිව ධනය උපයා එය භුක්ති විඳින ගිහියා ලබන සැප හතරෙන් 'අත්ථි සුඛ' යනු කුමක්ද?", "දැහැමිව උපයාගත් ධනය තමා සතු බව සිතා ලබන සතුට", "ණය නැති සතුට", "නිවැරදි ජීවිතයක සතුට", "දන් දීමෙන් ලබන සතුට", "අණණ සූත්‍රයේ දැක්වෙන පළමු ආර්ථික සුවය අත්ථි සුඛයයි."),
    q("අණණ සූත්‍රයේ දැක්වෙන ගිහි සැප හතරෙන් 'භෝග සුඛ' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "උපයාගත් ධනය තමා, පවුල හා පින්කම් වෙනුවෙන් පරිභෝජනය කර ලබන සතුට", "ධනය සඟවා තබා ගැනීමේ සතුට", "ණය ගැනීමේ සතුට", "අනුන්ගේ දේ ගැනීමේ සතුට", "මසුරු නොවී තම අවශ්‍යතා ඉටු කර ගැනීමේ හා පින් කිරීමේ සතුට භෝග සුඛයයි."),
    q("අණණ සූත්‍රයේ 'අණණ සුඛ' යනුවෙන් අදහස් කරන ඉතා වැදගත් ආර්ථික සුවය කුමක්ද?", "කිසිවෙකුටත් ණය නැති බව සිතා ලබන මානසික නිදහස", "බොහෝ ණය ලබා ගැනීම", "බැංකු පොලී ගෙවීම", "මිතුරන්ගෙන් මුදල් ඉල්ලීම", "අයවැය පාලනය කරමින් ණය බරින් මිදී ජීවත් වීම උතුම් සුවයකි."),
    q("අණණ සූත්‍රයේ අවසන් හා උතුම්ම ගිහි සුවය වන 'අනවජ්ජ සුඛ' යනු කුමක්ද?", "නිවැරදි කාය, වචී, මනෝ කර්මවලින් යුක්ත නිදොස් ජීවිතයක සතුට", "වැඩිපුර ආහාර ගැනීම", "සැණකෙළි බැලීම", "ලොතරැයි දිනුම් ඇදීම", "සදාචාරවත් නිදොස් ජීවිතයක් ගත කිරීමෙන් ලැබෙන ආධ්‍යාත්මික සතුටයි."),
    q("ධනය රැස් කර ගෙන තමාත් ප්‍රයෝජනයට නොගෙන අනුන්ටත් නොදෙන පුද්ගලයා බුදුදහමේ උපමා කර ඇත්තේ කුමකටද?", "පිපාසිතයන්ට බොන්නට බැරි අමනුෂ්‍ය අරක්ගත් විලකට", "මහා සාගරයට", "වැසි වළාකුළකට", "පිරිසිදු ගංගාවකට", "අපුත්තක සිටුතුමා අරභයා පරිභෝග නොකරන මසුරු ධනයේ නිසරු බව වදාළහ."),
    q("ධනවත් වුවත් කිසිවෙකුටත් ප්‍රයෝජනයක් නැතිව ධනය ගොඩගසා තැබීමේ ආදීනව දෙසුවේ කුමන සිටුතුමා මියගිය පසුද?", "අපුත්තක සිටුතුමා", "අනේපිඬු සිටුතුමා", "මිගාර සිටුතුමා", "ධනංජය සිටුතුමා", "දරුවන් නැති මසුරු අපුත්තක සිටු මියගිය පසු සියලු ධනය රාජසන්තක විය."),
    q("බෞද්ධ ආර්ථික දර්ශනය අනුව නිෂ්පාදනය හා පරිභෝජනය සිදුවිය යුත්තේ කවර සීමාවක් තුළද?", "අවශ්‍යතා සපුරා ගන්නා මධ්‍යම ප්‍රතිපදාව තුළ", "අසීමිත තෘෂ්ණාව අනුව", "ශරීරයට පීඩා වන සේ නිරාහාරව", "සම්පත් සියල්ල නාස්ති කරමින්", "අධිපරිභෝජනය හා දුගී දුප්පත් බව යන අන්ත දෙකම බුදුදහම බැහැර කරයි."),
    q("පටිච්චසමුප්පාද නීතියට අනුව රැකියා විරහිත බව හා දුප්පත්කම දුරු කිරීමට බෞද්ධ ආර්ථිකයේ අගය කරන මූලික ගුණය කුමක්ද?", "උට්ඨාන වීර්යය හා කුසලතා සංවර්ධනය", "අනුන්ගෙන් යැපීම", "කම්මැලිකම", "දෛවයට භාර දීම", "දක්ඛෝ අනලසෝ යනුවෙන් කාර්යක්ෂමතාව හා දක්ෂතාව ආර්ථික දියුණුවට හේතු වන බව දැක්වේ."),
    q("සම්පත් පරිභෝජනයේදී 'න ච පමාදෝ' හෙවත් ප්‍රමාද නොවී අරපිරිමැස්මෙන් කටයුතු කිරීමෙන් සිදුවන යහපත කුමක්ද?", "සම්පත් තිරසාරව පවත්වා ගැනීම හා අනාගත පරපුරට රැකගැනීම", "කඩිනමින් සම්පත් අවසන් වීම", "ණය බර වැඩි වීම", "සමාජ ගැටුම් වැඩි වීම", "නාස්තිය වැළැක්වීම තිරසාර සංවර්ධනයේ මූලික බෞද්ධ අංගයකි."),
    q("සංඝයා වහන්සේට පූජා කරන පරණ වූ සිවුරක් පවා ඉවත නොදමා පිළිවෙළකට නැවත භාවිත කරන අයුරු ආනන්ද හිමි උදේනි රජුට පැහැදිලි කළේ ඇයි?", "බෞද්ධ අරපිරිමැස්ම හා සම්පත් ප්‍රතිචක්‍රීකරණය පෙන්වීමට", "අලුත් සිවුරු නොමැති නිසා", "රජු බිය ගැන්වීමට", "විලාසිතා පෙන්වීමට", "පරණ සිවුරු ඇඳ ඇතිරිලි, පාපිසි හා මැටි බඳුන් බැඳීමට යොදාගන්නා බව පැවසූහ."),
    q("මිනිසා ස්වභාවික පරිසරයට ගරු කරමින් ජීවත් විය යුතු බව පෙන්වන 'වනරෝප සූත්‍රයේ' දැක්වෙන පුණ්‍ය ක්‍රියාවක් කුමක්ද?", "පැන් හල්, ඒදඬු, පාලම් හා මල් පලතුරු උයන් ඉදි කිරීම", "වනාන්තර කපා දැමීම", "ජල උල්පත් දූෂණය කිරීම", "වන සතුන් දඩයම් කිරීම", "පරිසරයට හිතකර කටයුතු සදාකාලික පින් වැඩෙන ක්‍රියා ලෙස වදාළහ."),
    q("බුදුරජාණන් වහන්සේගේ උපත, බුද්ධත්වය සහ පරිනිර්වාණය යන මංගල අවස්ථා තුනම සිදු වූයේ කොහිද?", "වෘක්ෂ මූල ආශ්‍රිත ස්වභාවික පරිසරයක", "මහා ප්‍රාසාද තුළ", "නාගරික වෙළඳපොළක", "යුද පිටියක", "ලුම්බිණි සල් උයන, ඇසතු බෝ මුල හා උපවත්තන සල් උයන ස්වභාවධර්මය සමඟ බැඳී ඇත."),
    q("භික්ෂූන් වහන්සේලාට ගස් කොළන් සිඳීම හා වෘක්ෂලතා විනාශ කිරීම තහනම් කරමින් පැනවූ විනය ශික්ෂාව කුමක්ද?", "භූතගාම සික්ඛාපදය", "අදත්තාදාන සික්ඛාපදය", "මුසාවාද සික්ඛාපදය", "සුරාමේරය සික්ඛාපදය", "නිල්ල පිරුණු ගස්වැල් කැපීම හා තෘණ විනාශ කිරීම පාචිත්තිය ඇවතක් ලෙස පනවා ඇත."),
    q("බුදු සසුනේ පිණ්ඩපාතයට පසු ගංගා ඇළ දොළ අපවිත්‍ර නොකිරීම පිළිබඳව විනය පිටකයේ දැක්වෙන නීතිය කුමක්ද?", "ජලයේ හා තණකොළ මත මළමුත්‍ර හා කුණුකසළ නොදැමීමේ සේඛියා නීති", "ජලය පානය නොකිරීම", "වැසි කාලයේ පිටතට නොයෑම", "ගඟෙන් එතෙර නොවීම", "ජල සම්පත පිරිසිදුව තබා ගැනීමට විනය නීති පවා පනවා තිබීම බුදුදහමේ පරිසර හිතකාමී බවයි."),
    q("ගිලන් හා වැසි කාලවලදී තණකොළ හා කුඩා ප්‍රාණීන් පෑගී විනාශ වීම වැළැක්වීමට බුදුරදුන් අනුමත කළ චාරිත්‍රය කුමක්ද?", "වස් විසීම", "කඨින පූජාව", "පිරිත් දේශනාව", "ධර්ම සංගායනාව", "වැසි සමයේ හටගන්නා තෘණ හා කුඩා සතුන් රැකීමට වස් කාලයේ එකම තැනක විසීම නියම කළහ."),
    q("අන්ධානුකරණයෙන් තොරව පරිසරයට ගරු කරමින් ශබ්ද දූෂණයෙන් තොරව කටයුතු කිරීම සඳහා භික්ෂූන්ට නියම කළ ගුණය කුමක්ද?", "අප්පසද්දකාමී බව (නිහඬතාව අගය කිරීම)", "උස් හඬින් කෑ ගැසීම", "වාද විවාද කිරීම", "සැණකෙළි පැවැත්වීම", "වනයේ නිහඬ සුන්දරත්වය විඳිමින් භාවනාවට හිතකර නිහඬ පරිසරය රැකීම අගය කෙරේ."),
    q("පරිසරයේ සුන්දරත්වය හා භාවනාවට ඇති හිතකර බව ඉතා අලංකාරවත් ලෙස වර්ණනා කර ඇති බෞද්ධ ග්‍රන්ථය කුමක්ද?", "ථේර-ථේරී ගාථා", "අභිධම්මත්ථ සංගහය", "කථාවත්ථුප්පකරණය", "පාතිමෝක්ෂය", "කාලුදායි, මහා කාශ්‍යප, තාලපුට ආදී තෙරුන්ගේ ගාථාවල වන සුන්දරත්වය වර්ණනා වේ."),
    q("'යස්ස රුක්ඛස්ස ඡායාය නිසීදෙය්‍ය සයෙය්‍ය වා' යන ගාථාවෙන් කුමන පාරිසරික සදාචාරයක් උගන්වයිද?", "සෙවණ දුන් ගසක අත්තක් හෝ නොකැඩිය යුතු බව (මිත්‍රද්‍රෝහී නොවීම)", "සෙවණ ඇති ගස් කපා දැමිය යුතු බව", "වනය ගිනි තැබිය යුතු බව", "ගස් මුල් උදුරා දැමිය යුතු බව", "පරිසරයෙන් ලද උපකාරයට කෘතගුණ සැලකීමක් ලෙස ගස්වැල් රැකිය යුතුය."),
    q("මිහිඳු මහරහතන් වහන්සේ දෙවනපෑතිස් රජුට මුව දඩයමේදී දුන් ඓතිහාසික පාරිසරික පණිවිඩය කුමක්ද?", "රජු රටේ හිමිකරු නොව භාරකරු බවත් සතුන්ට හා පක්ෂීන්ටත් මෙහි නිදහස ඇති බවත්ය", "සියලු සතුන් දඩයම් කළ හැකි බව", "වනාන්තර එළි කළ යුතු බව", "රජුට සියලු සතුන් මැරීමේ අයිතිය ඇති බව", "සියලු ජීවීන්ට පරිසරයේ ජීවත් වීමට සම අයිතිය ඇති බව ලක්දිව ප්‍රථම වනෝද්‍යානය බිහි කරමින් පෙන්වූහ."),
    q("මිහිඳු හිමිගේ පාරිසරික දර්ශනය මත දේවානම්පියතිස්ස රජු විසින් ලොව ප්‍රථම අභයභූමිය ලෙස ප්‍රකාශ කළ උයන කුමක්ද?", "මහමෙවුනා උයන", "නන්දන උයන", "රන්මසු උයන", "හග්ගල උයන", "සියලු සතුන්ට අභය දුන් ලොව පැරණිතම වනජීවී ආරක්ෂිත කලාපයයි."),
    q("කෘෂිකාර්මික කටයුතු හා ජල සංරක්ෂණය සඳහා 'අහසින් වැටෙන එකදු දිය බිඳක්වත්...' යන ප්‍රකාශය කළ හෙළ රජු කවුද?", "මහා පරාක්‍රමබාහු රජතුමා", "දුටුගැමුණු රජතුමා", "වළගම්බා රජතුමා", "කාශ්‍යප රජතුමා", "බෞද්ධ සම්පත් සංරක්ෂණ චින්තනයෙන් ප්‍රේරණය වී වැව් අමුණු තැනූහ."),
    q("ධාර්මික ජීවිතයක් ගත කරන ගෘහපතියා වගකීමෙන් ඉටු කළ යුතු 'පංච බලි' අතර 'අතිථි බලි' යනු කුමක්ද?", "නිවසට පැමිණෙන ආගන්තුකයන්ට ආගන්තුක සත්කාර කිරීම", "රජුට බදු ගෙවීම", "මියගිය ඥාතීන්ට පින් දීම", "දෙවියන්ට පින් දීම", "පත්තකම්ම සූත්‍රයේ දැක්වෙන අතිථි සත්කාරය සමාජ බැඳීම් ශක්තිමත් කරයි."),
    q("පත්තකම්ම සූත්‍රයේ 'රාජ බලි' යනුවෙන් දැක්වෙන පුරවැසි ආර්ථික වගකීම කුමක්ද?", "රජයට නියමිත බදු නිසි පරිදි ගෙවීම", "අල්ලස් දීම", "බදු පැහැර හැරීම", "සොරකම් කිරීම", "රටේ පොදු සුබසිද්ධිය හා යටිතල පහසුකම් වෙනුවෙන් නිසි බදු ගෙවීම යුතුකමකි."),
    q("ධනය විනාශ වීමට හේතු වන 'අකාල විචරණය' යනු කුමක්ද?", "නොකල්හි රාත්‍රී වීදි සංචාරය කිරීම හා අවිනීත හැසිරීම", "දිවා කාලයේ රැකියාවට යාම", "වන්දනා ගමන් යාම", "උදෑසන ව්‍යායාම කිරීම", "සිඟාලෝවාද සූත්‍රයට අනුව රාත්‍රී අනවශ්‍ය සංචාරය ධනයට හා ජීවිත ආරක්ෂාවට තර්ජනයකි."),
    q("ධනය රැස් කළ පුද්ගලයෙකුට ඇතිවන ලෞකික සැපතට වඩා ධාර්මික සතුට වටිනා බව පෙන්වන්නේ කෙසේද?", "වැරදි ලෙස රැස් කළ ධනය බිය හා දුක ගෙන දෙන බැවින්", "ධනය සියල්ලට වඩා බලවත් බැවින්", "සතුට මුදලින් මිලදී ගත හැකි බැවින්", "දුප්පත් වීමම නිවන බැවින්", "අයුතු මාර්ගයෙන් ලද ධනය මානසික සාමය විනාශ කරයි."),
    q("බෞද්ධ ආර්ථික කළමනාකරණය අනුව 'ණය ගැනීම' සම්බන්ධයෙන් දෙන උපදේශය කුමක්ද?", "හැකි සෑම විටම ආදායමට සරිලන සේ ජීවත් වී ණය බරින් මිදීම", "විනෝදය සඳහා නිතර ණය ගැනීම", "ණය ආපසු නොගෙවා සිටීම", "මිතුරන්ගෙන් ණය ගෙන සූදු කෙළීම", "ණය බර දුකට හේතු වන බවත් 'අණණ සුඛ' උතුම් බවත් බුදුරදුන් වදාළහ."),
    q("වර්තමාන පරිසර දූෂණය හා ගෝලීය උණුසුම අවම කර ගැනීමට ගත හැකි ප්‍රායෝගික බෞද්ධ පියවරක් කුමක්ද?", "සරල අල්පේච්ඡ දිවි පෙවෙත හා රුක් රෝපණය", "කර්මාන්තශාලා අපද්‍රව්‍ය ගංගාවලට දැමීම", "අධික ප්ලාස්ටික් භාවිතය", "වනාන්තර ගිනි තැබීම", "ලෝභය පාලනය කර සොබාදහම රැකීමෙන් පාරිසරික අර්බුද විසඳිය හැකිය."),
    q("සියලු ප්‍රාණීන් කෙරෙහි මෙත් සිත පැතිරවීමේදී 'ථාවරා වා තසා වා' ලෙස කරණීයමෙත්ත සූත්‍රයේ දක්වා ඇත්තේ කුමක්ද?", "සංසාරයේ තැතිගන්නා පෘථග්ජන සතුන් හා නොසැලෙන රහතුන් යන සැමට මෙත් වැඩීම", "මිනිසුන්ට පමණක් මෙත් වැඩීම", "වන සතුන් මරා දැමීම", "ගස් කපා දැමීම", "දිග, කෙටි, මහත, කුඩා, ඇසට පෙනෙන නොපෙනෙන සියලු සතුන් මෙත් සිතින් රැකිය යුතුය."),
    q("වෙළඳාමේදී තම පාරිභෝගිකයාට ගුණාත්මක භාණ්ඩ සාධාරණ මිලට දීම කුමන ගුණයට අයත්ද?", "අවංක බව හා සම්මා ආජීවයට", "ලෝභයට", "මිථ්‍යා ආජීවයට", "කුසීතකමට", "වෙළඳාම සමාජ සේවයක් ලෙස සලකා සාධාරණව ඉටු කිරීම බෞද්ධ ආර්ථික ධර්මයයි."),
    q("නිසි වෙලාවට වැඩ කිරීමෙන් අතපසු නොකිරීමේ ගුණය 'සමුට්ඨාන' වීර්යය ලෙස අගය කරන්නේ ඇයි?", "ප්‍රමාදයෙන් සියලු ආර්ථික අවස්ථා ගිලිහී යන බැවින්", "වැඩි වේලාවක් නිදා ගත හැකි බැවින්", "රැකියාව අතහැරිය හැකි බැවින්", "වෙනත් අය ලවා වැඩ ගත හැකි බැවින්", "'අතිසීතං අතිඋණ්හං' යැයි කාලය නාස්ති නොකරන තැනැත්තා දියුණු වන බව සිඟාලෝවාද සූත්‍රයේ එයි."),
    q("වැඩ කිරීමට අලස පුද්ගලයන් කාලගුණයට හා වේලාවට දොස් පවරන ආකාර කීයක් සිඟාලෝවාද සූත්‍රයේ දැක්වේද?", "හයකි (සීතලයි, උණුසුම්, සවස් වුණා ආදී ලෙස)", "දෙකකි", "හතරකි", "දසයකි", "ඉතා සීතලයි, ඉතා උණුසුම්, ඉතා සවස්, ඉතා උදෑසන, ඉතා බඩගිනියි, ඉතා බඩපිරිලා යනු ඒ හයයි."),
    q("බෞද්ධ ආර්ථික දර්ශනය අනුව ධනය ඇති පුද්ගලයෙකු 'මහත් පල' ලැබෙන සේ ධනය වැය කළ යුතු ක්ෂේත්‍රය කුමක්ද?", "සමාජ සුබසාධනය, ගිලානෝපස්ථානය හා ධර්ම දානය", "සුරාසැල් විවෘත කිරීම", "අවි ආයුධ නිෂ්පාදනය", "මසුරුකමින් පෙට්ටගම්වල දැමීම", "අනුන්ගේ යහපතට යොදවන ධනය මෙලොව සතුට හා පරලොව පින උදා කරයි."),
    q("ලෝකයේ ස්වභාවික සම්පත් හා ඛනිජ සම්පත් පරිභෝජනයේදී බුදුදහම උගන්වන ප්‍රධාන මූලධර්මය කුමක්ද?", "අවශ්‍ය පමණට පමණක් ගෙන ස්වභාවධර්මයේ සමතුලිතතාව රැකීම", "එකවර සියල්ල හාරා ගැනීම", "පරිසරයට විෂ අපද්‍රව්‍ය මුදා හැරීම", "වන සතුන් වඳ කර දැමීම", "සොබාදහමට අනුව ජීවත් වීමෙන් සියලු සත්වයන් සුරක්ෂිත වේ."),
    q("බෞද්ධ සමාජයේ ජල සම්පත සංරක්ෂණයට පැරණි රජවරුන් පවා දායක වූයේ කෙසේද?", "වැව්, අමුණු හා පොකුණු ඉදිකර සශ්‍රීක කෘෂි සංස්කෘතියක් ගොඩනැගීමෙන්", "ගංගා වසා දැමීමෙන්", "වැව් ගොඩ කර ගෙවල් තැනීමෙන්", "කැලෑ සම්පූර්ණයෙන් ගිනි තැබීමෙන්", "ධර්මාශෝක හා දේවානම්පියතිස්ස රජවරුන්ගේ සිට වැව් හා දාගැබ් සංකල්පය බිහි විය."),
    q("බුදුරදුන් වදාළ පරිදි 'සැබෑ ධනවතා' ලෙස හඳුන්වනු ලබන්නේ කවුද?", "සද්ධා, සීල ආදී සප්ත ආර්ය ධනයෙන් පොහොසත් හා ලද දෙයින් සතුටු වන තැනැත්තා", "රන් කහවණු කෝටි ගණනක් සඟවාගෙන සිටින්නා", "මසුරුකමින් ජීවත් වන්නා", "අනුන්ගේ දේ පැහැර ගන්නා", "සන්තුට්ඨි පරමං ධනං (සතුට උතුම්ම ධනයයි) යනු බෞද්ධ ඉගැන්වීමයි.")
  )
}
